import { StudySheet, WordItem, ExpressionItem, StructureItem, ParticleItem } from '../types';

/**
 * Parses exported .txt files (or JSON backups) back into a fully formed StudySheet.
 * Works seamlessly with files generated by Sawasdee Talk.
 */
export function parseStudySheetFromText(rawText: string, filename: string = 'fiche_importee.txt'): StudySheet | null {
  try {
    const trimmed = rawText.trim();

    // Check if it's already JSON
    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
      const parsed = JSON.parse(trimmed);
      if (parsed.stats && parsed.words && parsed.expressions) {
        return {
          id: parsed.id || 'imported_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
          createdAt: parsed.createdAt || new Date().toISOString(),
          dateFormatted: parsed.dateFormatted || new Date().toLocaleDateString('fr-FR'),
          title: parsed.title || filename.replace('.txt', ''),
          durationSeconds: parsed.durationSeconds || parsed.stats?.durationSeconds || 60,
          stats: parsed.stats,
          words: parsed.words || [],
          expressions: parsed.expressions || [],
          structures: parsed.structures || [],
          particles: parsed.particles || [],
          pedagogicalAdvice: parsed.pedagogicalAdvice || '',
        };
      }
    }

    const lines = rawText.split('\n').map((l) => l.trim());

    let dateFormatted = new Date().toLocaleDateString('fr-FR');
    let title = filename.replace('.txt', '').replace(/^thai_vocabulaire_/, 'Conversation du ');
    let durationFormatted = '1 min 00 s';
    let durationSeconds = 60;

    // Read header lines
    for (const line of lines) {
      if (line.startsWith('Date de la conversation')) {
        const val = line.split(':')[1]?.trim();
        if (val) dateFormatted = val;
      } else if (line.startsWith('Thème / Contexte')) {
        const val = line.split(':')[1]?.trim();
        if (val) title = val;
      } else if (line.startsWith('Durée analysée')) {
        const val = line.split(':')[1]?.trim();
        if (val) {
          durationFormatted = val.split('(')[0]?.trim() || val;
          const matchSec = val.match(/\((\d+)s\)/);
          if (matchSec) durationSeconds = parseInt(matchSec[1], 10);
        }
      }
    }

    // Parse Sections
    const words: WordItem[] = [];
    const expressions: ExpressionItem[] = [];
    const structures: StructureItem[] = [];
    const particles: ParticleItem[] = [];

    let currentSection: 'none' | 'stats' | 'words' | 'expressions' | 'structures' | 'particles' | 'advice' = 'none';

    // Temp accumulators
    let curWord: Partial<WordItem> | null = null;
    let curExp: Partial<ExpressionItem> | null = null;
    let curStruct: Partial<StructureItem> | null = null;
    let curPart: Partial<ParticleItem> | null = null;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      if (line.includes('1. STATISTIQUES')) {
        currentSection = 'stats';
        continue;
      } else if (line.includes('2. MOTS THAÏS LES PLUS UTILISÉS')) {
        currentSection = 'words';
        continue;
      } else if (line.includes('3. EXPRESSIONS THAÏES LES PLUS UTILES')) {
        if (curWord && curWord.thai) words.push(curWord as WordItem);
        curWord = null;
        currentSection = 'expressions';
        continue;
      } else if (line.includes('4. STRUCTURES LINGUISTIQUES')) {
        if (curExp && (curExp.thai || curExp.phonetic)) expressions.push(curExp as ExpressionItem);
        curExp = null;
        currentSection = 'structures';
        continue;
      } else if (line.includes('5. PARTICULES ET MOTS DE LIAISON')) {
        if (curStruct && curStruct.structureThai) structures.push(curStruct as StructureItem);
        curStruct = null;
        currentSection = 'particles';
        continue;
      } else if (line.includes('CONSEILS PÉDAGOGIQUES')) {
        if (curPart && curPart.thai) particles.push(curPart as ParticleItem);
        curPart = null;
        currentSection = 'advice';
        continue;
      }

      // SECTION 2 : WORDS
      if (currentSection === 'words') {
        const occMatch = line.match(/^(\d+)\.\s*\[(\d+)\s*occurrence.*\]\s*(.+)$/);
        if (occMatch) {
          if (curWord && curWord.thai) words.push(curWord as WordItem);
          curWord = {
            occurrences: parseInt(occMatch[2], 10),
            thai: occMatch[3].trim(),
            phonetic: '',
            pronunciationFr: '',
            tone: 'Ton plat',
            french: '',
            category: 'Général',
            exampleThai: '',
            exampleFrench: '',
          };
          continue;
        }

        if (curWord) {
          if (line.startsWith('Phonétique (RTGS) :')) {
            curWord.phonetic = line.replace('Phonétique (RTGS) :', '').trim();
          } else if (line.startsWith('Prononciation FR  :')) {
            const raw = line.replace('Prononciation FR  :', '').trim();
            const toneMatch = raw.match(/\((.*?)\)/);
            if (toneMatch) {
              curWord.tone = toneMatch[1];
              curWord.pronunciationFr = raw.replace(/\(.*?\)/, '').trim();
            } else {
              curWord.pronunciationFr = raw;
            }
          } else if (line.startsWith('Sens en français  :')) {
            curWord.french = line.replace('Sens en français  :', '').trim();
          } else if (line.startsWith('Catégorie         :')) {
            curWord.category = line.replace('Catégorie         :', '').trim();
          } else if (line.startsWith('Exemple naturel   :')) {
            curWord.exampleThai = line.replace('Exemple naturel   :', '').trim();
          } else if (line.startsWith('Traduction exemple:')) {
            curWord.exampleFrench = line.replace('Traduction exemple:', '').trim();
          }
        }
      }

      // SECTION 3 : EXPRESSIONS
      if (currentSection === 'expressions') {
        const occMatch = line.match(/^(\d+)\.\s*\[(\d+)\s*occurrence.*\]\s*(.+)$/);
        if (occMatch) {
          if (curExp && (curExp.thai || curExp.phonetic)) expressions.push(curExp as ExpressionItem);
          curExp = {
            occurrences: parseInt(occMatch[2], 10),
            thai: occMatch[3].trim(),
            phonetic: '',
            pronunciationFr: '',
            french: '',
            context: 'Quotidien',
            contextTag: 'autre',
            exampleThai: '',
            exampleFrench: '',
          };
          continue;
        }

        if (curExp) {
          if (line.startsWith('Phonétique (RTGS) :')) {
            curExp.phonetic = line.replace('Phonétique (RTGS) :', '').trim();
          } else if (line.startsWith('Prononciation FR  :')) {
            curExp.pronunciationFr = line.replace('Prononciation FR  :', '').trim();
          } else if (line.startsWith('Traduction        :')) {
            curExp.french = line.replace('Traduction        :', '').trim();
          } else if (line.startsWith("Contexte d'emploi :")) {
            const ctx = line.replace("Contexte d'emploi :", '').trim();
            curExp.context = ctx;
            const lower = ctx.toLowerCase();
            if (lower.includes('salu') || lower.includes('poli')) curExp.contextTag = 'salutation';
            else if (lower.includes('quest') || lower.includes('prix') || lower.includes('combien')) curExp.contextTag = 'question';
            else if (lower.includes('accord') || lower.includes('conclu')) curExp.contextTag = 'accord';
            else if (lower.includes('demand') || lower.includes('command') || lower.includes('baiss')) curExp.contextTag = 'demande';
            else curExp.contextTag = 'quotidien';
          } else if (line.startsWith('Exemple pratique  :')) {
            curExp.exampleThai = line.replace('Exemple pratique  :', '').trim();
          } else if (line.startsWith('Traduction exemple:')) {
            curExp.exampleFrench = line.replace('Traduction exemple:', '').trim();
          }
        }
      }

      // SECTION 4 : STRUCTURES
      if (currentSection === 'structures') {
        const structMatch = line.match(/^Structure\s*\d+\s*:\s*(.+)$/);
        if (structMatch) {
          if (curStruct && curStruct.structureThai) structures.push(curStruct as StructureItem);
          curStruct = {
            structureThai: structMatch[1].trim(),
            meaningFrench: '',
            grammarExplanation: '',
            exampleThai: '',
            exampleFrench: '',
          };
          continue;
        }

        if (curStruct) {
          if (line.startsWith('Signification         :')) {
            curStruct.meaningFrench = line.replace('Signification         :', '').trim();
          } else if (line.startsWith('Règle grammaticale    :')) {
            curStruct.grammarExplanation = line.replace('Règle grammaticale    :', '').trim();
          } else if (line.startsWith('Exemple réutilisable  :')) {
            curStruct.exampleThai = line.replace('Exemple réutilisable  :', '').trim();
          } else if (line.startsWith("Traduction de l'ex.   :")) {
            curStruct.exampleFrench = line.replace("Traduction de l'ex.   :", '').trim();
          }
        }
      }

      // SECTION 5 : PARTICLES
      if (currentSection === 'particles') {
        const partMatch = line.match(/^•\s*(.*?)\s*\((.*?)\)\s*\[(.*?)\]/);
        if (partMatch) {
          if (curPart && curPart.thai) particles.push(curPart as ParticleItem);
          curPart = {
            thai: partMatch[1].trim(),
            phonetic: partMatch[2].trim(),
            category: (partMatch[3].toLowerCase() as any) || 'politesse',
            role: '',
            speakerRegister: '',
            exampleUsage: '',
          };
          continue;
        }

        if (curPart) {
          if (line.startsWith('Rôle               :')) {
            curPart.role = line.replace('Rôle               :', '').trim();
          } else if (line.startsWith('Registre / Emploi  :')) {
            curPart.speakerRegister = line.replace('Registre / Emploi  :', '').trim();
          } else if (line.startsWith("Exemple d'emploi   :")) {
            curPart.exampleUsage = line.replace("Exemple d'emploi   :", '').trim();
          }
        }
      }
    }

    // Flush any pending items
    if (curWord && curWord.thai) words.push(curWord as WordItem);
    if (curExp && (curExp.thai || curExp.phonetic)) expressions.push(curExp as ExpressionItem);
    if (curStruct && curStruct.structureThai) structures.push(curStruct as StructureItem);
    if (curPart && curPart.thai) particles.push(curPart as ParticleItem);

    // If nothing parsed, return null
    if (words.length === 0 && expressions.length === 0) {
      return null;
    }

    const sheet: StudySheet = {
      id: 'import_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7),
      createdAt: new Date().toISOString(),
      dateFormatted,
      title: title || 'Fiche importée',
      durationSeconds,
      stats: {
        durationSeconds,
        durationFormatted,
        totalSpokenWordsApprox: words.reduce((a, b) => a + (b.occurrences || 1), 0) * 3,
        distinctThaiWords: words.length,
        distinctThaiExpressions: expressions.length,
        repeatedExpressionsCount: expressions.filter((e) => e.occurrences > 1).length,
        totalOccurrencesCount: expressions.reduce((a, b) => a + (b.occurrences || 1), 0),
        top5Words: words.slice(0, 5).map((w) => ({ thai: w.thai, phonetic: w.phonetic, french: w.french, count: w.occurrences })),
        top5Expressions: expressions.slice(0, 5).map((e) => ({ thai: e.thai, phonetic: e.phonetic, french: e.french, count: e.occurrences })),
        segmentationNote: 'Fiche importée depuis un export texte UTF-8.',
      },
      words,
      expressions,
      structures,
      particles,
      pedagogicalAdvice: 'Fiche d\'expressions restaurée avec succès.',
    };

    return sheet;
  } catch (err) {
    console.warn('Erreur parsing fiche:', err);
    return null;
  }
}

/**
 * Reads up to 5 files asynchronously and parses them into StudySheet objects.
 */
export async function parseMultipleSheetFiles(files: FileList | File[]): Promise<{
  successSheets: StudySheet[];
  errorCount: number;
}> {
  const fileArray = Array.from(files).slice(0, 5); // limit to 5 files as requested
  const successSheets: StudySheet[] = [];
  let errorCount = 0;

  for (const file of fileArray) {
    try {
      const text = await file.text();
      const parsed = parseStudySheetFromText(text, file.name);
      if (parsed) {
        successSheets.push(parsed);
      } else {
        errorCount++;
      }
    } catch {
      errorCount++;
    }
  }

  return { successSheets, errorCount };
}
